CREATE DEFINER=`root`@`localhost` PROCEDURE `cercanegozi`(in lat double, in lon double)
BEGIN
select * from negozi
where (6371 * acos(
    COS(RADIANS(lat)) * COS(RADIANS(latitudine)) *
        COS(RADIANS(longitudine) - RADIANS(lon)) +
        SIN(RADIANS(lat)) * SIN(RADIANS(latitudine))
    )) <= 4;
END ;;
