CREATE DEFINER=`root`@`localhost` PROCEDURE `login`(in var_username varchar(45), in var_pass varchar(45), out var_role int)
BEGIN
declare var_user_role ENUM('Negoziante', 'Utente'); 
select ruolo from user 
where username = var_username and password = md5(var_pass) 
into var_user_role; 
if var_user_role = 'Negoziante' then 
set var_role = 1; 
elseif var_user_role = 'Utente' then 
set var_role = 2; 
else 
set var_role = 3; 
end if;
END ;;
DELIMITER ;
